input.command:
docker exec cli-eval-opencode-phpoffice__phpspreadsheet-3463-fd32b4c7 sh -lc 'cd /testbed && php -r "
require \"vendor/autoload.php\";
use PhpOffice\PhpSpreadsheet\Spreadsheet;
use PhpOffice\PhpSpreadsheet\Writer\Xlsx;
\$s = new Spreadsheet();
\$ws = \$s->getActiveSheet();
\$ws->setCellValue(\"A1\", \"=NETWORKDAYS(DATE(2023,1,1),DATE(2023,1,31))\");
\$ws->setCellValue(\"A2\", \"=DAYS(DATE(2023,1,31),DATE(2023,1,1))\");
\$ws->setCellValue(\"A3\", \"=ABS(NETWORKDAYS(A1:A2, B1))\");
\$w = new Xlsx(\$s);
\$o = fopen(\"php://memory\", \"r+\");
\$w->save(\"/tmp/opencode/t.xlsx\");
\$zip = new ZipArchive();
\$zip->open(\"/tmp/opencode/t.xlsx\");
\$xml = \$zip->getFromName(\"xl/worksheets/sheet1.xml\");
preg_match_all(\"/<f>(.*?)<\/f>/\", \$xml, \$m);
print_r(\$m[1]);
"'

